-- FinDost AI schema (generated by backend/scripts/export_schema.py)

CREATE TABLE IF NOT EXISTS budgets (
	id VARCHAR(36) NOT NULL, 
	business_id VARCHAR(36) NOT NULL, 
	category VARCHAR(60) NOT NULL, 
	monthly_amount_paisa BIGINT NOT NULL, 
	created_at TIMESTAMP WITH TIME ZONE NOT NULL, 
	updated_at TIMESTAMP WITH TIME ZONE NOT NULL, 
	PRIMARY KEY (id), 
	CONSTRAINT uq_budget_category UNIQUE (business_id, category), 
	CONSTRAINT ck_budget_amount CHECK (monthly_amount_paisa > 0), 
	FOREIGN KEY(business_id) REFERENCES businesses (id) ON DELETE CASCADE
);
CREATE INDEX IF NOT EXISTS ix_budgets_business_id ON budgets (business_id);
ALTER TABLE public."budgets" ENABLE ROW LEVEL SECURITY;

CREATE TABLE IF NOT EXISTS finance_actions (
	id VARCHAR(36) NOT NULL, 
	business_id VARCHAR(36) NOT NULL, 
	title VARCHAR(200) NOT NULL, 
	description VARCHAR(1000), 
	source_type VARCHAR(16) NOT NULL, 
	source_ref VARCHAR(120), 
	adjustments JSON NOT NULL, 
	estimated_impact_paisa BIGINT, 
	impact_basis VARCHAR(300), 
	due_on DATE, 
	requires_approval BOOLEAN NOT NULL, 
	status VARCHAR(18) NOT NULL, 
	created_by VARCHAR(64) NOT NULL, 
	decided_by VARCHAR(64), 
	decided_at TIMESTAMP WITH TIME ZONE, 
	decision_note VARCHAR(500), 
	completed_by VARCHAR(64), 
	completed_at TIMESTAMP WITH TIME ZONE, 
	outcome_note VARCHAR(500), 
	created_at TIMESTAMP WITH TIME ZONE NOT NULL, 
	updated_at TIMESTAMP WITH TIME ZONE NOT NULL, 
	PRIMARY KEY (id), 
	CONSTRAINT ck_action_status CHECK (status IN ('proposed', 'pending_approval', 'approved', 'rejected', 'completed', 'cancelled')), 
	FOREIGN KEY(business_id) REFERENCES businesses (id) ON DELETE CASCADE
);
CREATE INDEX IF NOT EXISTS ix_finance_actions_business_id ON finance_actions (business_id);
CREATE INDEX IF NOT EXISTS ix_finance_actions_created_at ON finance_actions (created_at);
ALTER TABLE public."finance_actions" ENABLE ROW LEVEL SECURITY;

CREATE TABLE IF NOT EXISTS savings_goals (
	id VARCHAR(36) NOT NULL, 
	business_id VARCHAR(36) NOT NULL, 
	name VARCHAR(80) NOT NULL, 
	target_paisa BIGINT NOT NULL, 
	saved_paisa BIGINT NOT NULL, 
	target_date DATE NOT NULL, 
	created_at TIMESTAMP WITH TIME ZONE NOT NULL, 
	updated_at TIMESTAMP WITH TIME ZONE NOT NULL, 
	PRIMARY KEY (id), 
	CONSTRAINT ck_goal_target CHECK (target_paisa > 0), 
	CONSTRAINT ck_goal_saved CHECK (saved_paisa >= 0), 
	FOREIGN KEY(business_id) REFERENCES businesses (id) ON DELETE CASCADE
);
CREATE INDEX IF NOT EXISTS ix_savings_goals_business_id ON savings_goals (business_id);
ALTER TABLE public."savings_goals" ENABLE ROW LEVEL SECURITY;

CREATE TABLE IF NOT EXISTS workspace_invitations (
	id VARCHAR(36) NOT NULL, 
	business_id VARCHAR(36) NOT NULL, 
	email VARCHAR(254) NOT NULL, 
	role VARCHAR(10) NOT NULL, 
	token_hash VARCHAR(64) NOT NULL, 
	status VARCHAR(10) NOT NULL, 
	expires_at TIMESTAMP WITH TIME ZONE NOT NULL, 
	invited_by VARCHAR(64) NOT NULL, 
	accepted_by VARCHAR(64), 
	accepted_at TIMESTAMP WITH TIME ZONE, 
	email_sent BOOLEAN NOT NULL, 
	created_at TIMESTAMP WITH TIME ZONE NOT NULL, 
	PRIMARY KEY (id), 
	CONSTRAINT ck_invite_role CHECK (role IN ('owner', 'editor', 'viewer')), 
	CONSTRAINT ck_invite_status CHECK (status IN ('pending', 'accepted', 'revoked')), 
	FOREIGN KEY(business_id) REFERENCES businesses (id) ON DELETE CASCADE, 
	UNIQUE (token_hash)
);
CREATE INDEX IF NOT EXISTS ix_workspace_invitations_business_id ON workspace_invitations (business_id);
ALTER TABLE public."workspace_invitations" ENABLE ROW LEVEL SECURITY;

CREATE TABLE IF NOT EXISTS workspace_members (
	id VARCHAR(36) NOT NULL, 
	business_id VARCHAR(36) NOT NULL, 
	user_id VARCHAR(64) NOT NULL, 
	email VARCHAR(254), 
	role VARCHAR(10) NOT NULL, 
	status VARCHAR(10) NOT NULL, 
	invited_by VARCHAR(64), 
	created_at TIMESTAMP WITH TIME ZONE NOT NULL, 
	updated_at TIMESTAMP WITH TIME ZONE NOT NULL, 
	PRIMARY KEY (id), 
	CONSTRAINT uq_member_workspace_user UNIQUE (business_id, user_id), 
	CONSTRAINT ck_member_role CHECK (role IN ('owner', 'editor', 'viewer')), 
	CONSTRAINT ck_member_status CHECK (status IN ('active', 'removed')), 
	FOREIGN KEY(business_id) REFERENCES businesses (id) ON DELETE CASCADE
);
CREATE INDEX IF NOT EXISTS ix_workspace_members_user_id ON workspace_members (user_id);
CREATE INDEX IF NOT EXISTS ix_workspace_members_business_id ON workspace_members (business_id);
ALTER TABLE public."workspace_members" ENABLE ROW LEVEL SECURITY;
